SELECT MAX(consumption::double precision) AS highest_monthly_consumption
FROM public.yearmonth
WHERE LEFT(date, 4) = '2012';

SELECT EXISTS (
  SELECT 1
  FROM public.laboratory AS l
  JOIN public.patient AS p ON p.id = l.id
  WHERE l.id = 57266
    AND (
      (p.sex = 'M' AND l.ua > 8.0)
      OR (p.sex = 'F' AND l.ua > 6.5)
    )
) AS uric_acid_within_normal_range;

SELECT player_name
FROM public.player
WHERE SUBSTRING(birthday, 1, 7) = '1970-10';

SELECT
  100.0 * COUNT(*) FILTER (
    WHERE EXTRACT(YEAR FROM p.creaiondate) = 2011
      AND u.reputation > 1000
  ) / NULLIF(COUNT(*) FILTER (
    WHERE EXTRACT(YEAR FROM p.creaiondate) = 2011
  ), 0) AS percentage
FROM public.posts AS p
LEFT JOIN public.users AS u
  ON u.id = p.owneruserid;

SELECT
  COUNT(*) FILTER (WHERE LOWER(bordercolor) = 'borderless') * 100.0 / NULLIF(COUNT(*), 0) AS percentage_borderless_cards
FROM public.cards;

SELECT id
FROM public.cards
WHERE LOWER(dueldeck) = 'a';

SELECT ROUND(100.0 * COUNT(*) FILTER (WHERE element = 'h') / NULLIF(COUNT(atom_id), 0), 4) AS percentage
FROM public.atom
WHERE molecule_id = 'TR206';

SELECT
  100.0 * SUM(amount) FILTER (WHERE status = 'A') / NULLIF(SUM(amount), 0) AS percentage_fully_paid
FROM public.loan;

SELECT COUNT(*) AS tsc
FROM public.sales
WHERE sale_date BETWEEN CURRENT_DATE - INTERVAL '6 days' AND CURRENT_DATE;
